class Solution {
public:
    long long countSubstrings(string s, char c) {
        long long m = 0;
        for (char ch : s) if (ch == c) m++;
        return m * (m + 1) / 2;
    }
};

class Solution {
    public long countSubstrings(String s, char c) {
        long m = 0;
        for (char ch : s.toCharArray()) if (ch == c) m++;
        return m * (m + 1) / 2;
    }
}

var countSubstrings = function(s, c) {
    let m = 0n;
    for (const ch of s) if (ch === c) m++;
    return Number(m * (m + 1n) / 2n);
